 {
  "turns": [
    {
      "speaker": "customer",
      "text": "I am so tired of these hidden charges on my bill! This is absolutely ridiculous and I'm done with this service.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Yeah, what's the problem?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I'm Vivek Patel and I'm paying for a plan I don't even use. I want to change my plan to the basic one immediately or I'm switching to another provider today.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "Which phone number are we talking about?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 98911 17158.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see the account. Which plan do you want?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "The basic one. I've already sent emails from vivek.85@examplemail.com and nobody replied to me for three days!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am switching you to the basic plan now.",
      "tags": [
        "action:plan_change"
      ]
    },
    {
      "speaker": "customer",
      "text": "Finally! I just wanted this sorted out without all the stress.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will process the plan change and send a confirmation SMS to your device.",
      "tags": [
        "action:plan_change"
      ]
    },
    {
      "speaker": "customer",
      "text": "Thank you, I appreciate you actually getting it done quickly.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else? I have updated the plan and you will receive the SMS shortly. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
